package net.zartra.gui;
import org.bukkit.entity.Player;import java.util.*;
final class ChatInputManager { interface Callback { void run(Player player,String text); } private final Map<UUID,Entry> map=Collections.synchronizedMap(new HashMap<UUID,Entry>());private final long ttl; ChatInputManager(long seconds){ttl=Math.max(10,seconds)*1000L;} boolean begin(Player p,Callback cb){if(map.containsKey(p.getUniqueId()))return false;map.put(p.getUniqueId(),new Entry(System.currentTimeMillis(),cb));return true;} boolean pending(Player p){return map.containsKey(p.getUniqueId());} Entry take(Player p){return map.remove(p.getUniqueId());}boolean expired(Entry entry){return entry==null||System.currentTimeMillis()-entry.time>ttl;}void remove(Player p){map.remove(p.getUniqueId());}void clear(){map.clear();}static final class Entry{final long time;final Callback cb;Entry(long t,Callback c){time=t;cb=c;}} }
